def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    # Initialize the grid to represent the classroom with chat pairs
    classroom = [[0] * N for _ in range(M)]

    # Mark the chat pairs in the classroom grid
    for (X, Y, P, Q) in chatting_pairs:
        classroom[X-1][Y-1] += 1
        classroom[P-1][Q-1] += 1

    # Function to add a horizontal aisle and count separable chat pairs
    def add_horizontal_aisle(row):
        separable_pairs = 0
        for col in range(N):
            if classroom[row][col] > 0:
                classroom[row][col] = 0
                for P in range(M):
                    if classroom[P][col] > 0:
                        classroom[P][col] -= 1
                        separable_pairs += 1
        return separable_pairs

    # Function to add a vertical aisle and count separable chat pairs
    def add_vertical_aisle(col):
        separable_pairs = 0
        for row in range(M):
            if classroom[row][col] > 0:
                classroom[row][col] = 0
                for P in range(N):
                    if classroom[row][P] > 0:
                        classroom[row][P] -= 1
                        separable_pairs += 1
        return separable_pairs

    # Find the best K horizontal aisles and L vertical aisles
    horizontal_aisles = []
    for _ in range(K):
        best_row, best_separations = None, 0
        for row in range(M):
            separations = add_horizontal_aisle(row)
            if separations > best_separations:
                best_row, best_separations = row, separations
        horizontal_aisles.append(best_row + 1)
        add_horizontal_aisle(best_row)

    vertical_aisles = []
    for _ in range(L):
        best_col, best_separations = None, 0
        for col in range(N):
            separations = add_vertical_aisle(col)
            if separations > best_separations:
                best_col, best_separations = col, separations
        vertical_aisles.append(best_col + 1)
        add_vertical_aisle(best_col)

    # Format the results as strings
    horizontal_aisles_str = ' '.join(map(str, horizontal_aisles))
    vertical_aisles_str = ' '.join(map(str, vertical_aisles))

    return (horizontal_aisles_str, vertical_aisles_str)

def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    # Initialize a 2D array to store the maximum happiness values
    dp = [[0 for _ in range(n + 1)] for _ in range(m + 1)]

    # Fill the dp array using a bottom-up approach
    for i in range(1, m + 1):
        price, importance = items[i - 1]
        for w in range(1, n + 1):
            if price <= w:
                dp[i][w] = max(dp[i - 1][w], dp[i - 1][w - price] + importance * price)
            else:
                dp[i][w] = dp[i - 1][w]

    # The maximum happiness value is stored in dp[m][n]
    return dp[m][n]

